const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.headers['idempotency-key'];
  if (!idempotencyKey) return res.status(400).json({ error: "Idempotency-Key header required" });

  const existing = await db.query(
    "SELECT order_id FROM idempotency_keys WHERE key = $1 AND account_id = $2 AND expires_at > now()",
    [idempotencyKey, req.user.accountId]
  );

  if (existing.length) {
    const order = await db.query(
      "SELECT * FROM orders WHERE id = $1",
      [existing[0].order_id]
    );
    return res.status(201).json(order[0]);
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  await db.write(
    "INSERT INTO idempotency_keys (key, account_id, order_id, expires_at) VALUES ($1, $2, $3, now() + interval '24 hours')",
    [idempotencyKey, req.user.accountId, row.id]
  );

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(403).end();
  res.json(row);
});

module.exports = router;
